/// The errors package runs declares, with native.NewError, which Go
/// compares with errors.Is. Return one as Err(RunsError::…into()).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RunsError {
}

impl RunsError {
    /// The error's code, which Go knows it by.
    pub fn code(&self) -> &'static str {
        match *self {
        }
    }

    fn from_code(code: &str) -> Option<Self> {
        match code {
            _ => None,
        }
    }
}

impl From<RunsError> for Error {
    fn from(e: RunsError) -> Self { Error::Module(e) }
}

// The functions Go calls.

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_init(cb: Callback, id_base: u64, malloc: Malloc, free: Free) {
    let _ = RUNTIME.set(Runtime { cb, id_base, malloc, free });
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_new_RunService(obj: u64, args: *const u8, n: usize, call: u64) -> *mut u8 {
    run(|_w| {
        let v: Arc<dyn RunService> = crate::make_run_service()?;
        _w.u64(retain(Obj::RunService(v)));
        Ok(())
    })
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_RunService_LoadRun(obj: u64, args: *const u8, n: usize, call: u64) -> *mut u8 {
    start(|| {
        let _o = obj_run_service(obj)?;
        let _a = &mut Reader::new(args, n);
        let _p0 = _a.string()?;
        task(call, move |_ctx, _w| {
            let _r = _o.load_run(_ctx, _p0)?;
            enc_RunSnapshot(_w, &_r);
            Ok(())
        });
        Ok(())
    })
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_RunService_ListRuns(obj: u64, args: *const u8, n: usize, call: u64) -> *mut u8 {
    start(|| {
        let _o = obj_run_service(obj)?;
        task(call, move |_ctx, _w| {
            let _r = _o.list_runs(_ctx)?;
            enc_slice_RunSummary(_w, &_r);
            Ok(())
        });
        Ok(())
    })
}

