pub unsafe extern "C" fn mygo_runs_new_MixPlanService(obj: u64, args: *const u8, n: usize, call: u64) -> *mut u8 {
    run(|_w| {
        let v: Arc<dyn MixPlanService> = crate::make_mix_plan_service()?;
        _w.u64(retain(Obj::MixPlanService(v)));
        Ok(())
    })
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_MixPlanService_PlateMixPlan(obj: u64, args: *const u8, n: usize, call: u64) -> *mut u8 {
    start(|| {
        let _o = obj_mix_plan_service(obj)?;
        let _a = &mut Reader::new(args, n);
        let _p0 = dec_PlateMixInput(_a)?;
        task(call, move |_ctx, _w| {
            let _r = _o.plate_mix_plan(_ctx, _p0)?;
            enc_PlateMixResult(_w, &_r);
            Ok(())
        });
        Ok(())
    })
}

/// An object of the implementation that Go holds, by its handle.
enum Obj {
    RunService(Arc<dyn RunService>),
    DesignService(Arc<dyn DesignService>),
    TimeBudgetService(Arc<dyn TimeBudgetService>),
    MixPlanService(Arc<dyn MixPlanService>),
    Closer(Arc<dyn Closer>),
}

fn obj_run_service(h: u64) -> Result<Arc<dyn RunService>, Error> {
    match object(h)? {
        Obj::RunService(o) => Ok(Arc::clone(o)),
        _ => Err(Error::Go("Go passed an object that is not a RunService".into())),
    }
}

fn obj_design_service(h: u64) -> Result<Arc<dyn DesignService>, Error> {
    match object(h)? {
        Obj::DesignService(o) => Ok(Arc::clone(o)),
        _ => Err(Error::Go("Go passed an object that is not a DesignService".into())),
    }
}

fn obj_time_budget_service(h: u64) -> Result<Arc<dyn TimeBudgetService>, Error> {
    match object(h)? {
        Obj::TimeBudgetService(o) => Ok(Arc::clone(o)),
        _ => Err(Error::Go("Go passed an object that is not a TimeBudgetService".into())),
    }
}

fn obj_mix_plan_service(h: u64) -> Result<Arc<dyn MixPlanService>, Error> {
    match object(h)? {
        Obj::MixPlanService(o) => Ok(Arc::clone(o)),
        _ => Err(Error::Go("Go passed an object that is not a MixPlanService".into())),
    }
}

fn close_obj(o: &Obj) -> Result<(), Error> {
    match o {
        Obj::RunService(o) => o.close(),
        Obj::DesignService(o) => o.close(),
        Obj::Closer(o) => o.close(),
        _ => Ok(()),
    }
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_close(obj: u64, args: *const u8, n: usize, call: u64) -> *mut u8 {
    run(|_| close_obj(object(obj)?))
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_release(obj: u64) {
    if obj != 0 {
        let _ = guard(|| drop(Box::from_raw(obj as *mut Obj)));
    }
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_cancel(call: u64) {
    let _ = guard(|| cancel(call));
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_next(call: u64) {
    let _ = guard(|| demand(call));
}

#[no_mangle]
pub unsafe extern "C" fn mygo_runs_resume(cont: u64, block: *mut u8) {
    let _ = guard(|| resume(cont, block));
}

